import { describe, it } from "vitest";

describe("MHPCO Claim Office", () => {
  describe("quote: processing fee and base premiums", () => {
    it.todo("empty item list -> premium 5 G (only the processing fee)");
    it.todo("sword -> 100 G base premium");
    it.todo("amulet -> 60 G base premium");
    it.todo("staff -> 80 G base premium");
    it.todo("potion -> 40 G base premium");
    it.todo("sword + amulet -> policy base premium 160 G (sum of item base premiums)");
    it.todo("rune -> 25 G base premium");
    it.todo("moonstone -> 25 G base premium");
    it.todo("2 runes -> 50 G base premium");
    it.todo("3 runes -> 60 G base premium (block applies)");
    it.todo("4 runes -> 100 G base premium (no block: block requires exactly 3)");
    it.todo("7 runes -> 175 G base premium");
    it.todo("2 runes + 1 moonstone -> 75 G base premium (no block: different types)");
    it.todo("3 runes + 3 moonstones -> 120 G base premium (two separate blocks)");
    it.todo(
      "unknown item type broomstick -> quote is rejected (reading: the domain throws an Error naming the type; the CLI turns it into a non-zero exit)",
    );
  });

  describe("quote: premium modifiers", () => {
    it.todo("plain sword, newcomer's first contract -> 115 G (100 base + 10 first insurance + 5 fee)");
    it.todo("newcomer with a cursed sword (steel, enchantment 3) -> 165 G (100 + 50 curse + 10 first insurance + 5 fee)");
    it.todo("sword with exactly enchantment 5, not cursed -> 145 G (high-enchantment surcharge 30 applies)");
    it.todo("sword with enchantment 4, not cursed -> 115 G (no high-enchantment surcharge, no curse surcharge)");
    it.todo("cursed sword with exactly enchantment 5 -> 195 G (both surcharges apply: 50 + 30)");
    it.todo("cursed sword with enchantment 4 -> 165 G (only the curse surcharge applies)");
    it.todo(
      "cursed sword + plain amulet -> 231 G (base 160; curse adds 50 = 50 % of the sword's base premium, not of the policy total; + 16 first insurance + 5 fee)",
    );
    it.todo(
      "plain sword + amulet with enchantment 5 -> 199 G (high-enchantment adds 18 = 30 % of the amulet's base premium; + 16 first insurance + 5 fee)",
    );
    it.todo(
      "cursed rune -> 45 G (reading: the curse surcharge applies to a component's own base premium: 25 + 12.5 curse + 2.5 first insurance + 5 fee)",
    );
    it.todo("customer with exactly 2 years with MHPCO, plain sword -> 95 G (100 - 20 loyalty + 10 first insurance + 5 fee)");
    it.todo("customer with 1 year with MHPCO, plain sword -> 115 G (no loyalty discount)");
    it.todo(
      "customer with 3 years, cursed sword -> 145 G (loyalty 20 = 20 % of the policy base premium, not of the surcharged amount)",
    );
    it.todo("follow-up contract (one previous contract), newcomer, plain sword -> 100 G (100 + 10 first insurance - 15 follow-up + 5 fee)");
    it.todo("rounding in the MHPCO's favor: 7 runes for a newcomer yield 197.5 G -> premium 198 G (rounded up)");
    it.todo(
