import { describe, it } from "vitest";

describe("MHPCO Claim Office", () => {
  describe("quote: processing fee and base premiums", () => {
    it.todo("empty item list -> premium 5 G (only the processing fee)");
    it.todo("sword -> 100 G base premium");
    it.todo("amulet -> 60 G base premium");
    it.todo("staff -> 80 G base premium");
    it.todo("potion -> 40 G base premium");
    it.todo("sword + amulet -> policy base premium 160 G (sum of item base premiums)");
    it.todo("rune -> 25 G base premium");
    it.todo("moonstone -> 25 G base premium");
    it.todo("2 runes -> 50 G base premium");
    it.todo("3 runes -> 60 G base premium (block applies)");
    it.todo("4 runes -> 100 G base premium (no block: block requires exactly 3)");
    it.todo("7 runes -> 175 G base premium");
    it.todo("2 runes + 1 moonstone -> 75 G base premium (no block: different types)");
    it.todo("3 runes + 3 moonstones -> 120 G base premium (two separate blocks)");
    it.todo(
      "unknown item type broomstick -> quote is rejected (reading: the domain throws an Error naming the type; the CLI turns it into a non-zero exit)",
    );
  });

  describe("quote: premium modifiers", () => {
    it.todo("plain sword, newcomer's first contract -> 115 G (100 base + 10 first insurance + 5 fee)");
    it.todo("newcomer with a cursed sword (steel, enchantment 3) -> 165 G (100 + 50 curse + 10 first insurance + 5 fee)");
    it.todo("sword with exactly enchantment 5, not cursed -> 145 G (high-enchantment surcharge 30 applies)");
    it.todo("sword with enchantment 4, not cursed -> 115 G (no high-enchantment surcharge, no curse surcharge)");
    it.todo("cursed sword with exactly enchantment 5 -> 195 G (both surcharges apply: 50 + 30)");
    it.todo("cursed sword with enchantment 4 -> 165 G (only the curse surcharge applies)");
    it.todo(
      "cursed sword + plain amulet -> 231 G (base 160; curse adds 50 = 50 % of the sword's base premium, not of the policy total; + 16 first insurance + 5 fee)",
    );
    it.todo(
      "plain sword + amulet with enchantment 5 -> 199 G (high-enchantment adds 18 = 30 % of the amulet's base premium; + 16 first insurance + 5 fee)",
    );
    it.todo(
      "cursed rune -> 45 G (reading: the curse surcharge applies to a component's own base premium: 25 + 12.5 curse + 2.5 first insurance + 5 fee)",
    );
    it.todo("customer with exactly 2 years with MHPCO, plain sword -> 95 G (100 - 20 loyalty + 10 first insurance + 5 fee)");
    it.todo("customer with 1 year with MHPCO, plain sword -> 115 G (no loyalty discount)");
    it.todo(
      "customer with 3 years, cursed sword -> 145 G (loyalty 20 = 20 % of the policy base premium, not of the surcharged amount)",
    );
    it.todo("follow-up contract (one previous contract), newcomer, plain sword -> 100 G (100 + 10 first insurance - 15 follow-up + 5 fee)");
    it.todo("rounding in the MHPCO's favor: 7 runes for a newcomer yield 197.5 G -> premium 198 G (rounded up)");
    it.todo(
      "intermediate amounts stay fractional: 2 cursed runes for a newcomer -> 85 G (50 + 2 x 12.5 curse + 5 first insurance + 5 fee, not 86)",
    );
  });

  describe("policy: insurance sum and cap (twice the insurance sum)", () => {
    it.todo("sword -> insurance sum 1000 G, cap 2000 G");
    it.todo("amulet -> insurance sum 600 G, cap 1200 G");
    it.todo("staff -> insurance sum 800 G, cap 1600 G");
    it.todo("potion -> insurance sum 400 G, cap 800 G");
    it.todo("rune -> insurance sum 250 G, cap 500 G");
    it.todo("moonstone -> insurance sum 250 G, cap 500 G");
    it.todo("sword + amulet -> insurance sum 1600 G, cap 3200 G");
    it.todo("two swords -> insurance sum 2000 G, cap 4000 G");
    it.todo("cursed sword -> cap 2000 G (premium modifiers do not raise the cap)");
    it.todo("sword + 3 runes (a block) -> insurance sum 1750 G, cap 3500 G (block discount does not affect the insurance sum)");
  });

  describe("claim: payout", () => {
    it.todo("regular sword (steel, enchantment 3), damage 500 G -> payout 400 G, remaining cap 1600 G");
    it.todo("rune, damage 200 G -> payout 100 G (no special clause for components)");
    it.todo("steel sword, enchantment 9, damage 1000 G -> payout 400 G (50 % first, then deductible)");
    it.todo("steel sword, enchantment 7, damage 1000 G -> payout 900 G (below the enchantment 8 threshold: full reimbursement minus deductible)");
    it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G -> payout 400 G (high-enchantment clause applies, then deductible)");
    it.todo("dragon-material sword, enchantment 9, damage 1000 G -> payout 400 G (the 50 % rule wins over dragon material)");
    it.todo("dragon-material sword, enchantment 5, damage 800 G -> payout 700 G (full reimbursement, then deductible)");
    it.todo("dragon attack damages a sword (500 G) and an amulet (300 G) -> payout 600 G (deductible once per damaged item)");
    it.todo("two insured swords, two sword damage entries (500 G and 300 G) -> payout 600 G (each entry has its own deductible)");
    it.todo(
      "sword damage 500 G + amulet damage 50 G -> payout 400 G (reading: a damage below the deductible pays nothing and never reduces other entries)",
    );
    it.todo("rounding in the MHPCO's favor: steel sword, enchantment 9, damage 901 G yields 350.5 G -> payout 350 G (rounded down)");
    it.todo("intermediate amounts stay fractional: two enchantment-9 swords, damage 901 G each -> payout 701 G (350.5 + 350.5)");
    it.todo(
      "two sword damages but only one sword insured -> the whole claim is rejected (reading: the domain throws an Error; the CLI turns it into a non-zero exit)",
    );
    it.todo("amulet damaged when only a sword is insured -> claim is rejected (throws an Error)");
    it.todo("damage entry with an unknown item type (broomstick) -> claim is rejected (throws an Error)");
    it.todo("damage entry with amount -200 -> claim is rejected (throws an Error)");
  });

  describe("scenario: sequential steps", () => {
    it.todo(
      "schema example: 5 years, quote silver amulet (enchantment 2), claim fire damage 200 G -> results [{premium: 59}, {payout: 100, remainingCap: 1100}]",
    );
    it.todo("the customer's second quote in a scenario is a follow-up contract: newcomer, two plain sword quotes -> premiums 115 G and 100 G");
    it.todo("every contract after the first gets the follow-up discount: three plain sword quotes -> premiums 115 G, 100 G, 100 G");
    it.todo(
      "long-standing customer's second contract: 3 years, second quote, cursed sword (steel, enchantment 7) -> 160 G (100 + 50 + 30 - 20 + 10 - 15 + 5)",
    );
    it.todo("a claim refers to its policy by zero-based step index: quote sword, quote amulet, claim policy 1 amulet 300 G -> payout 200 G, remainingCap 1000 G");
    it.todo(
      "cap exhaustion: sword insured, two successive claims of 1500 G -> first payout 1400 G / remaining 600 G, second payout 600 G / remaining 0 G",
    );
    it.todo("the cap is tracked per policy: two sword policies, one 1500 G claim each -> both payout 1400 G, remainingCap 600 G");
    it.todo(
      "claim whose policy index does not refer to an earlier quote step -> rejected (reading: an unresolvable policy reference is an invalid claim; throws an Error)",
    );
  });

  describe("claim-office CLI (stdin JSON -> stdout JSON)", () => {
    it.todo('schema example on stdin -> exit 0, stdout {"results":[{"premium":59},{"payout":100,"remainingCap":1100}]}, empty stderr');
    it.todo("quote with unknown item type broomstick -> non-zero exit, error description on stderr, no results on stdout");
