import type { Policy } from "./policy.js";
import type { Item } from "./price-list.js";

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Settlement {
  payout: number;
  remainingCap: number;
}

const REDUCED_REIMBURSEMENT_ENCHANTMENT = 8;
const REDUCED_REIMBURSEMENT_RATE = 0.5;
const DEDUCTIBLE = 100;

function damagePayout(damage: Damage, damagedItem: Item | undefined): number {
  const reimbursement =
    (damagedItem?.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT
      ? damage.amount * REDUCED_REIMBURSEMENT_RATE
      : damage.amount;
  return reimbursement - DEDUCTIBLE;
}

export function settleClaim(policy: Policy, damages: Damage[]): Settlement {
  const damage = damages[0];
  const damagedItem = policy.items.find((item) => item.type === damage.itemType);
  const payout = damagePayout(damage, damagedItem);
  return { payout, remainingCap: policy.remainingCap - payout };
}

