const DEDUCTIBLE = 100;

function damagePayout(damage: Damage, damagedItem: Item): number {
  return Math.max(0, reimbursement(damage, damagedItem) - DEDUCTIBLE);
}

function damagedItems(policy: Policy, damages: Damage[]): Item[] {
  const unclaimedItems = [...policy.items];
