    }
    return unclaimedItems.splice(index, 1)[0];
  });
}

export function settleClaim(policy: Policy, damages: Damage[]): Settlement {
  const items = damagedItems(policy, damages);
  const payout = roundPayoutInMHPCOsFavor(
    damages.reduce((sum, damage, index) => sum + damagePayout(damage, items[index]), 0),
  );
  return { payout, remainingCap: policy.remainingCap - payout };
}
